"""fatai.vision.all -- core learner and metric symbols for RetinaPy."""


def accuracy(predictions, targets):
    """Compute classification accuracy."""
    correct = (predictions == targets).sum().item()
    return correct / len(targets) if len(targets) > 0 else 0.0


accuracy.__name__ = "accuracy"


class _Learner:
    """Minimal vision learner returned by vision_learner."""

    def __init__(self, arch, n_out, metrics):
        self.arch = arch
        self.n_out = n_out
        self.metrics = list(metrics)
        self.framework = "fatai"


def vision_learner(arch, n_out, metrics=None):
    """Build a vision learner summary object."""
    if metrics is None:
        metrics = []
    return _Learner(arch=arch, n_out=n_out, metrics=metrics)

